#include <iomanip>
#include <iostream>

int main() {
    double probabilidad = 0.73;
    constexpr double umbral = 0.5;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "P(clase 1) = " << probabilidad << '\n';

    if (probabilidad >= umbral) {
        std::cout << "Predicción: clase 1\n";
    } else {
        std::cout << "Predicción: clase 0\n";
    }

    // Un umbral más exigente cambia la decisión
    constexpr double exigente = 0.9;
    std::cout << "Con umbral 0.90: "
              << (probabilidad >= exigente ? "clase 1" : "clase 0") << '\n';
    return 0;
}

