#include <iostream>

int main() {
    double temperatura = 38.5;

    if (temperatura >= 39.0) {
        std::cout << "Fiebre alta\n";
    } else if (temperatura >= 37.5) {
        std::cout << "Fiebre\n";
    } else if (temperatura >= 36.0) {
        std::cout << "Normal\n";
    } else {
        std::cout << "Hipotermia\n";
    }
    return 0;
}

